const TAG_LIST = [...REST_TAGS].sort((a, b) => b.length - a.length);
/** "Fine dining Classic Light" → ["Fine dining", "Classic", "Light"] (some tags are two words). */
const splitTags = (s: string) => { const out: string[] = []; let rest = " " + s + " "; for (const t of TAG_LIST) if (rest.includes(" " + t + " ")) { out.push(t); rest = rest.replace(" " + t + " ", "  "); } return REST_TAGS.filter((t) => out.includes(t)); };
const lumHex = (h: string) => {
  const n = parseInt(h.slice(1), 16);
  const v = [(n >> 16) & 255, (n >> 8) & 255, n & 255].map((x) => { x /= 255; return x <= 0.03928 ? x / 12.92 : Math.pow((x + 0.055) / 1.055, 2.4); });
  return 0.2126 * v[0] + 0.7152 * v[1] + 0.0722 * v[2];
};
const NO_FX = Object.fromEntries(FX_KEYS.map((k) => [k, "none"])) as Theme["fx"];

export type RestTheme = Theme & { rest: { bands: string; menuStyle: string; divider: string; ornament: string; gallery: string } };
export const REST_THEMES: RestTheme[] = ROWS.map(([slug, name, tags, cols, display, body, radius, style, blurb, extra]) => {
  const c = cols.split(" "), s = style.split(" ");
  if (c.length !== 9 || s.length !== 15) throw new Error("Bad restaurant theme row: " + slug);
  const [layout, nav, cards, buttons, heading, shead, pattern, bands, heroArt, motionStyle, width, menuStyle, divider, ornament, gallery] = s;
  const x = extra ? extra.split(" ") : [];
  if (extra && x.length !== 8) throw new Error("Bad restaurant theme extras: " + slug);
  return {
    id: "rest-" + slug, name, tags: splitTags(tags), dark: lumHex(c[0]) < 0.2, blurb,
    colors: { bg: c[0], surface: c[1], deep: c[2], text: c[3], soft: c[4], line: c[5], c1: c[6], c2: c[7], c3: c[8] },
    display, body, radius,
    style: { layout, heroArt, nav, cards, buttons, motionStyle, pattern, ornament: "none", heading, shead, width },
    portfolio: { about: "bento", skills: "cube", work: "deck", glow: false, network: false, three: false, ticker: false },
    store: { grid: "auto", product: "classic" },
    fx: x.length ? { cursor: x[0], loader: x[1], textfx: x[2], hoverfx: x[3], scrollfx: x[4], overlay: x[5] } : NO_FX,
    motif: x[7] || "geometric", kit: "classic", ...(x[6] ? { herofx: x[6] } : {}), rest: { bands, menuStyle, divider, ornament, gallery },
  };
});

/** Stable IDs for restaurant themes: R-001 … in the order above. Add new themes at the end only. */
export const REST_CODES: Record<string, string> = Object.fromEntries(REST_THEMES.map((t, i) => [t.id, "R-" + String(i + 1).padStart(3, "0")]));
export const isRestTheme = (id: string) => id.startsWith("rest-");
/** What makes a theme's look its own, as one string (used to check that no two are alike). */
export const restSignature = (t: RestTheme) => [t.style.layout, t.style.heroArt, t.style.nav, t.rest.menuStyle, t.style.pattern, t.rest.divider, t.rest.ornament, t.rest.gallery].join(" ");

const ok = (axis: string, v: unknown, d: string) => (REST_AXES[axis].options.some(([x]) => x === v) ? (v as string) : d);
/** Restaurant content.theme values for a theme. */
export function restaurantThemeValues(t: Theme): Record<string, unknown> {
  const c = t.colors, s = t.style, r = (t as Partial<RestTheme>).rest;
  return {
    bg: c.bg, surface: c.surface, deep: c.deep, text: c.text, soft: c.soft, line: c.line, c1: c.c1, c2: c.c2, c3: c.c3,
    fontDisplay: t.display, fontBody: t.body, radius: t.radius, preset: t.id,
    layout: ok("layout", s.layout, "split"), heroArt: ok("heroArt", s.heroArt, "default"), nav: ok("nav", s.nav, "bar"),
    cards: ok("cards", s.cards, "outline"), buttons: ok("buttons", s.buttons, "rounded"), heading: ok("heading", s.heading, "normal"), shead: ok("shead", s.shead, "label"),
    pattern: ok("pattern", s.pattern, "none"), bands: ok("bands", r?.bands, "soft"), menuStyle: ok("menuStyle", r?.menuStyle, "classic"), divider: ok("divider", r?.divider, "none"),
    ornament: ok("ornament", r?.ornament, "none"), gallery: ok("gallery", r?.gallery, "grid"),
    motionStyle: ok("motionStyle", s.motionStyle, "rise"), width: s.width === "wide" ? "wide" : "normal",
    ...t.fx, ...(t.herofx ? { herofx: t.herofx } : {}), ...(t.motif !== "geometric" ? { motif: t.motif } : {}), introBg: c.deep, introFg: onColor(c.deep),
  };
}
